def get_series_list():
    seen = {}
    for mid, spec in HAMMOND_CATALOG.items():
        if spec['series'] not in seen:
            seen[spec['series']] = spec['series_name']
    return list(seen.items())
def find_hammond_for_board(board_w, board_h, component_height, series=None):
    fits = []
    for mid, spec in HAMMOND_CATALOG.items():
        if series and spec['series'] != series:
            continue
        margin_w = spec.get('margin_w', 3.0)
        margin_h = spec.get('margin_h', 3.0)
        fit_w = board_w + 2 * margin_w <= spec['interior_l']
        fit_h = board_h + 2 * margin_h <= spec['interior_w']
        fit_z = component_height + 2.0 <= spec['interior_h']
        if fit_w and fit_h and fit_z:
            volume = spec['interior_l'] * spec['interior_w'] * spec['interior_h']
            fits.append((mid, spec, volume))
    fits.sort(key=lambda x: x[2])
    return [(mid, spec) for mid, spec, _ in fits]
def build_snap_fit(doc, board_w, board_h, component_height, wall_t=2.5, floor_t=2.0, margin=2.0, mounting_holes=None, connector_cutouts=None):
    from enclosure_builder import EnclosureBuilder
    clearance = 0.5
    snap_count = 4
    vent_slots = 3
    boss_od = 6.0
    x_min = 0.0
    y_min = 0.0
    board_data = {'dimensions': {'width': float(board_w), 'height': float(board_h), 'x_min': x_min, 'y_min': y_min, 'x_max': float(board_w), 'y_max': float(board_h)}, 'mounting_holes': [{'x': h['x'], 'y': h['y'], 'diameter': h.get('diameter', 3.2)} for h in mounting_holes or []], 'components': [], 'edge_connectors': []}
    if connector_cutouts:
        for c in connector_cutouts:
            cx = c['x']
            cy = {'front': 0, 'back': board_h, 'left': 0, 'right': board_w}.get(c['side'], 0)
            board_data['edge_connectors'].append({'x': cx, 'y': cy, 'width': c['w'], 'height': c['h'], 'name': c.get('name', 'user_cutout')})
    builder = EnclosureBuilder(doc=doc)
    builder.create_base_shell(board_data, wall_t=wall_t, floor_t=floor_t, margin=margin)
    builder.add_mounting_bosses(board_data, boss_od=boss_od)
    if connector_cutouts:
        builder.add_connector_cutouts(board_data, clearance=clearance)
    if snap_count > 0:
        builder.add_snap_fits(count=snap_count)
    if vent_slots > 0:
        builder.add_ventilation(slot_count=vent_slots)
    builder.create_lid(board_data)
    return builder
def build_hammond(doc, model, connector_cutouts=None):
    import FreeCAD
    from enclosure_builder import EnclosureBuilder
    spec = HAMMOND_CATALOG.get(model)
    if not spec:
        return (False, f'Unknown Hammond model: {model}', None)
    try:
        builder = EnclosureBuilder(doc=doc)
        outer = doc.addObject('Part::Box', f'{model}_Outer')
        outer.Label = f'{model}_Outer'
        outer.Length = spec['outer_l']
        outer.Width = spec['outer_w']
        outer.Height = spec['outer_h']
        inner = doc.addObject('Part::Box', f'{model}_Cavity')
        inner.Label = f'{model}_Cavity'
        inner.Length = spec['interior_l']
        inner.Width = spec['interior_w']
        inner.Height = spec['interior_h']
        offset_l = (spec['outer_l'] - spec['interior_l']) / 2
        offset_w = (spec['outer_w'] - spec['interior_w']) / 2
        inner.Placement = FreeCAD.Placement(FreeCAD.Vector(offset_l, offset_w, spec['floor_t']), FreeCAD.Rotation())
        shell_arr = doc.addObject('Part::MultiFuse', f'{model}_Base')
        shell_arr.Label = f'{model}_Base'
        shell_arr.Shapes = [outer, inner]
        base = doc.addObject('Part::Cut', f'{model}_BaseCut')
        base.Label = f'{model}_Base'
        base.Base = shell_arr
        base.Tool = inner
        base = doc.addObject('Part::Cut', f'{model}_Base')
        base.Label = f'{model}_Base'
        base.Base = outer
        base.Tool = inner
        builder._add_to_doc(f'{model}_Base', base.Shape)
        lid = doc.addObject('Part::Box', f'{model}_Lid')
        lid.Label = f'{model}_Lid'
        lid.Length = spec['outer_l']
        lid.Width = spec['outer_w']
        lid.Height = spec['floor_t']
        lid.Placement = FreeCAD.Placement(FreeCAD.Vector(0, 0, spec['outer_h'] - spec['floor_t']), FreeCAD.Rotation())
        if connector_cutouts:
            _apply_side_cutouts(doc, builder, spec, connector_cutouts)
        doc.recompute()
        return (True, f'Built {model} enclosure.', builder)
    except Exception as e:
        import traceback
        traceback.print_exc()
        return (False, f'Hammond build failed: {type(e).__name__}: {e}', None)
def _apply_side_cutouts(doc, builder, spec, cutouts):
    import FreeCAD
    for c in cutouts:
        side = c.get('side', '').lower()
        cx = c['x']
        z = c['z']
        w = c['w']
        h = c['h']
        outer_l = spec['outer_l']
        outer_w = spec['outer_w']
        wall_t = spec['wall_t']
        if side == 'front':
            pos = FreeCAD.Vector(cx, outer_w / 2, z)
        elif side == 'back':
            pos = FreeCAD.Vector(cx, -outer_w / 2, z)
        elif side == 'left':
            pos = FreeCAD.Vector(-outer_l / 2, cx, z)
        elif side == 'right':
            pos = FreeCAD.Vector(outer_l / 2, cx, z)
        else:
            continue
        cut = doc.addObject('Part::Box', f'Cutout_{side}_{cx}')
        cut.Label = f'Cutout_{side}_{cx}'
        cut.Length = w + wall_t * 2
        cut.Width = wall_t * 2
        cut.Height = h
        cut.Placement = FreeCAD.Placement(pos, FreeCAD.Rotation())
if __name__ == '__main__':
    print(f'Hammond catalog — {len(HAMMOND_CATALOG)} models')
    print('\nModels fitting a 72x48mm board, 18mm tall components:')
    fits = find_hammond_for_board(72, 48, 18)
    for mid, spec in fits[:8]:
        print(f"  {mid:12s}  {spec['outer_l']}x{spec['outer_w']}x{spec['outer_h']}mm  series={spec['series_name']}")
    print('\nModels fitting a 80x60mm board, 20mm tall components:')
    fits = find_hammond_for_board(80, 60, 20)
    for mid, spec in fits[:8]:
        ml = spec['outer_l']
        mw = spec['outer_w']
        mh = spec['outer_h']
        il = spec['interior_l']
        iw = spec['interior_w']
        ih = spec['interior_h']
        print(f'  {mid:12s}  {ml}x{mw}x{mh}mm  interior {il}x{iw}x{ih}mm  margins +{il - 80:.0f}W +{iw - 60:.0f}H +{ih - 20:.0f}Z')
    print('\nSeries:')
    for sid, sname in get_series_list():
        count = sum((1 for v in HAMMOND_CATALOG.values() if v['series'] == sid))
        print(f'  {sid} — {sname} ({count} models)')
    print('\nSnap-fit geometry check (80x60mm board, 20mm components):')
    bw, bh, ch, wt, ft = (80, 60, 20, 2.5, 2.0)
    cl, bt = (0.5, 1.6)
    outer_w = bw + 2 * cl + 2 * wt
    outer_h = bh + 2 * cl + 2 * wt
    inner_z = ft + bt + ch + cl
    base_z = inner_z + 1.5
    total_h = base_z + ft
    print(f'  Outer WxH:  {outer_w:.1f} x {outer_h:.1f} mm')
    print(f'  Inner Z:    {inner_z:.1f} mm (floor+pcb+components+clearance)')
    print(f'  Base Z:     {base_z:.1f} mm')
    print(f'  Lid:        {ft} mm plate + 3 mm skirt')
    print(f'  Total H:    {total_h:.1f} mm')
    print('\nAll checks passed.')
